import json, sys, os
D=os.path.dirname(__file__)
xg=json.load(open(D+'/xg.json'))
P={ # club: (ATT prior, DEFW prior)
'MCI':(1.39,0.80),'CHE':(1.37,0.90),'ARS':(1.28,0.70),'BRE':(1.21,0.99),'BHA':(0.90,1.00),'LIV':(1.18,0.85),
