    att={c:v/ma for c,v in att.items()}; dfw={c:v/md for c,v in dfw.items()}
    return att,dfw,imp,clips,rclips
if __name__=='__main__':
    n=int(sys.argv[1])
    att,dfw,imp,clips,rc=ratings(n)
    print('clips',clips,rc)
